# FastFinder visual theme\n#\n# Startup note:\n# Avoid a catch-all `QWidget { ... }` rule.  A global QWidget selector forces\n# every child widget to be re-polished and can make large PySide6 windows much\n# slower to construct on Windows.  Application font is set through QFont in\n# main.py; QSS below only targets controls that actually need custom painting.\n\nAPP_STYLESHEET = r"""\nQMainWindow, QDialog {\n    background: #f5f7fb;\n    color: #1f2937;\n}\n\nQFrame#Card {\n    background: #ffffff;\n    border: 1px solid #e5e7eb;\n    border-radius: 10px;\n}\n\nQLabel#TitleLabel {\n    font-size: 22px;\n    font-weight: 700;\n    color: #111827;\n}\n\nQLabel#SubtleLabel { color: #6b7280; }\nQLabel#ModeHint { color: #64748b; padding: 2px 4px; }\nQLabel#StatusPill {\n    background: #eef6ff;\n    color: #2563eb;\n    border: 1px solid #dbeafe;\n    border-radius: 9px;\n    padding: 5px 10px;\n}\n\nQLineEdit, QComboBox, QSpinBox, QKeySequenceEdit {\n    background: #ffffff;\n    color: #1f2937;\n    border: 1px solid #d7dce3;\n    border-radius: 7px;\n    padding: 7px 10px;\n    min-height: 22px;\n    selection-background-color: #2563eb;\n}\nQLineEdit:focus, QComboBox:focus, QSpinBox:focus, QKeySequenceEdit:focus {\n    border-color: #3b82f6;\n}\nQLineEdit#SearchEdit {\n    font-size: 16px;\n    padding: 10px 14px;\n    min-height: 26px;\n    border-radius: 9px;\n}\n\nQPushButton {\n    background: #ffffff;\n    color: #1f2937;\n    border: 1px solid #d7dce3;\n    border-radius: 7px;\n    padding: 7px 13px;\n    min-height: 24px;\n}\nQPushButton:hover { background: #f8fafc; border-color: #aab4c3; }\nQPushButton:pressed { background: #eef2f7; }\nQPushButton#PrimaryButton {\n    background: #2563eb;\n    color: white;\n    border-color: #2563eb;\n    font-weight: 600;\n}\nQPushButton#PrimaryButton:hover { background: #1d4ed8; }\nQPushButton#ModeButton { padding: 7px 16px; font-weight: 600; }\nQPushButton#ModeButton:checked {\n    color: white;\n    background: #2563eb;\n    border-color: #2563eb;\n}\nQPushButton#WarningButton {\n    color: #92400e;\n    border-color: #f4c98b;\n    background: #fffaf0;\n}\nQPushButton#WarningButton:hover { background: #fff4db; border-color: #eab35b; }\nQPushButton#DangerButton {\n    color: #b42318;\n    border-color: #f3b7b2;\n    background: #fff8f7;\n}\n\nQTableView, QTableWidget {\n    background: #ffffff;\n    alternate-background-color: #f9fbfd;\n    color: #1f2937;\n    border: 1px solid #e5e7eb;\n    gridline-color: #eef1f5;\n    selection-background-color: #dbeafe;\n    selection-color: #111827;\n}\nQHeaderView::section {\n    background: #f8fafc;\n    color: #475569;\n    border: none;\n    border-bottom: 1px solid #e5e7eb;\n    border-right: 1px solid #eef1f5;\n    padding: 7px 8px;\n    font-weight: 600;\n}\n\nQProgressBar {\n    background: #eef2f7;\n    border: none;\n    min-height: 7px;\n    max-height: 7px;\n}\nQProgressBar::chunk { background: #3b82f6; }\nQCheckBox { spacing: 8px; }\n\nQMenu { background: #ffffff; border: 1px solid #dfe3e8; padding: 5px; }\nQMenu::item { padding: 7px 24px 7px 10px; }\nQMenu::item:selected { background: #eff6ff; }\n\nQWidget#QuickSearchWindow { background: transparent; }\nQFrame#QuickCard {\n    background: #ffffff;\n    border: 1px solid #d8dee8;\n    border-radius: 14px;\n}\nQLineEdit#QuickSearchEdit {\n    font-size: 18px;\n    padding: 12px 14px;\n    min-height: 30px;\n    border: 2px solid #93b4f7;\n    border-radius: 10px;\n}\nQListWidget#QuickResultList {\n    background: #ffffff;\n    border: none;\n    outline: none;\n    font-size: 13px;\n}\nQListWidget#QuickResultList::item {\n    min-height: 46px;\n    padding: 6px 8px;\n    border-bottom: 1px solid #eef1f5;\n}\nQListWidget#QuickResultList::item:selected {\n    background: #dbeafe;\n    color: #111827;\n}\n"""\n